      if(e.target.classList.contains('knyrel-btn-save')){
        var sc=parseInt(card.querySelector('.knyrel-inp-score').value)||0;
        var lv=parseInt(card.querySelector('.knyrel-inp-lvl').value)||0;
        var st=card.querySelector('.knyrel-inp-status').value||'';
        var nt=card.querySelector('.knyrel-inp-note').value||'';
